<?php
namespace WPKit\SiteDoctor\Scanners; use WPKit\SiteDoctor\{SiteDoctorIssue,SiteDoctorScanner}; if(!defined('ABSPATH'))exit;
final class AISearchScanner implements SiteDoctorScanner{public function id():string{return 'ai-search';}public function label():string{return 'AI Search';}public function scan():array{$o=[];$home=home_url('/');$r=wp_safe_remote_get($home,['timeout'=>8]);if(is_wp_error($r))return $o;$h=wp_remote_retrieve_body($r);if(!preg_match('/application\\/ld\\+json/i',$h))$o[]=$this->i('no-schema','ai-search','medium','review_required','No JSON-LD detected','No JSON-LD structured data was detected on the homepage.','Add relevant schema through the site’s existing SEO/schema system.');if(!preg_match('/<main\b|<article\b/i',$h))$o[]=$this->i('weak-document-structure','ai-search','low','manual_only','Main content structure is unclear','No main/article landmark was detected in the homepage HTML.','Review the page structure for clear primary content.');return $o;}private function i($id,$c,$s,$r,$t,$d,$rec){return new SiteDoctorIssue(['id'=>$id,'category'=>$c,'severity'=>$s,'risk'=>$r,'title'=>$t,'description'=>$d,'recommendation'=>$rec]);}}
